B.bdb=new A.jm('Ein Snapshot ist eine "eingefrorene" Momentaufnahme aller Lagerbest\xe4nde zu einem bestimmten Stichtag. Er enth\xe4lt die genauen Mengen pro Lagerort und Holzart \u2014 und bleibt f\xfcr immer unver\xe4ndert, auch wenn sich der aktuelle Bestand danach \xe4ndert.',null)
B.bcQ=new A.jm("Snapshots sind besonders n\xfctzlich f\xfcr Jahres- und Quartalsabschl\xfcsse, f\xfcr Inventuren und um den Bestandsverlauf \xfcber l\xe4ngere Zeitr\xe4ume nachzuvollziehen.",null)
B.c0h=s([B.bdb,B.bcQ],t.p)
B.bdn=new A.ri("Was ist ein Snapshot?","info",B.d5,B.c0h,null)
B.b7w=new A.jP("event",B.hg,"Jahresabschluss",'F\xfcr den Stichtag 31.12. eines Jahres. Wird automatisch mit dem Titel "Jahresabschluss [Jahr]" angelegt.',null,null)
B.b7v=new A.jP("event_note",B.Bl,"Quartalsabschluss",'F\xfcr ein Quartal \u2014 z.B. "Q3 2025". Das richtige Quartal wird aus dem Stichtag automatisch ermittelt.',null,null)
B.b7A=new A.jP("fact_check",B.Bm,"Inventur",'Beliebiger Stichtag f\xfcr eine Bestandspr\xfcfung. Wird mit Datum betitelt: "Inventur 15.08.2025".',null,null)
B.b7I=new A.jP("tune",B.jC,"Sonstiges","Frei w\xe4hlbarer Titel \u2014 z.B. vor einer Software-Umstellung oder einer externen Pr\xfcfung.",null,null)
